-- composition of rule kernels column_lifetime x reorder_filter (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT AGE ((MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY 16) - '-1 month'::interval), DATE_TRUNC ('year', (SELECT MIN ('1999-12-31 23:59:59.999999+05:30'::timestamptz) FROM t4 AS a1))) AS c0, 45 AS c1, 40 AS c2) AS ka UNION ALL SELECT 2 AS k FROM (SELECT (-1) AS c0 FROM (tl AS a1 JOIN (t1 POSITIONAL JOIN t3) ON ((a1.c0 = t3.c0) AND t3.c1)) WHERE GREATEST (((t1.c2 = '{"k": -1, "a": [1, 2, 3]}'::jsonb) OR TRUE), t3.c1)) AS kb) AS u;
